// Checkout conversion fix: ensure paidEvents increment on successful payment
const { logEvent } = require('./eventLogger');

module.exports = function(req, res, next) {
  const originalSend = res.send.bind(res);
  res.send = function(body) {
    // Detect successful checkout response (e.g., status 200 with payment success)
    if (res.statusCode === 200 && body && typeof body === 'string' && body.includes('payment_success')) {
      logEvent('paidEvents', 1);
    }
    return originalSend(body);
  };
  next();
};
